import json
from pathlib import Path

root = Path(__file__).resolve().parent.parent
version = json.loads((root / "version.json").read_text(encoding="utf-8"))
print('- Профили CottenDNS из WhiteDNS теперь подключаются. Раньше при импорте терялись настройки профиля, в том числе пресет совместимости со старыми серверами MasterDNS и StormDNS, и клиент стучался к такому серверу в своём новом режиме, на который тот не отвечает. Теперь настройки сохраняются, применяются при запуске и не теряются при экспорте ссылки.')
print('- В редакторе профиля qWDTT появилась кнопка «Устройства на сервере». Она показывает, сколько устройств привязано к паролю и сколько из них активно, и позволяет отвязать это устройство. Это работает и для чужих подписок, без доступа к админке сервера.')
print('- Когда вы сами удаляете профиль qWDTT, это устройство отвязывается от сервера и место освобождается. Если остался другой профиль с тем же паролем, привязка сохраняется.')
print('- Профили qWDTT, CSQTT и WDTT Plus можно сохранить без хешей. Если хешей нет и источник не автоматический, при запуске будет понятная подсказка.')
print()
print(f"Основа: Throne {version['throne_version']}, коммит [{version['throne_commit'][:8]}](https://github.com/throneproj/Throne/commit/{version['throne_commit']}).")
